function faceColor(a){const valid=c=>/^#[0-9a-f]{6}$/i.test(c||''),head=a.parts?.find(part=>part.id==='head'),native={1:'#ffe0b1',2:'#f5d29d',3:'#ffe9c9',4:'#e0bc85',5:'#d2ac73',6:'#bf9c66',7:'#aa8956',8:'#957544'}[head?.path?.match(/Tint (\d+)/)?.[1]];return valid(head?.tint)?head.tint:native||(valid(a.palette?.head)?a.palette.head:'#eac58e');}
function shadeFace(a,factors){return '#'+faceColor(a).slice(1).match(/../g).map((n,i)=>Math.round(parseInt(n,16)*factors[i]).toString(16).padStart(2,'0')).join('');}
